def bind(text):
    def replace(m):
        name,n=m.group(1),int(m.group(2))
        if name not in ARITY:return m.group(0)
        if ARITY[name]!=n:raise ValueError(f'{name}: arity {n}, expected {ARITY[name]}')
        return f'NATIVE_CALL({name}, {n})'
    text=re.sub(r'(?<![A-Z_])CALL\((\w+),\s*(\d+)\)',replace,text)
    def context(m):
        body=m.group(2)
        if ('FIELD('not in body and 'ENTER('not in body)or'const int32_t reloq_machine_ref='in body:return m.group(0)
        initial=('    const int32_t reloq_machine_ref=\n'
                 '        nargs>0 && EVV_AT(void *,args[0])==state?args[0]:REG_REF(state);\n')
        return m.group(1)+initial+body+m.group(3)
    return re.sub(r'(static int32_t evv_\w+\(void \*state, const int32_t \*args, int nargs\)\n\{\n)(.*?)(\n\})',context,text,flags=re.S)
